self.KB_CONTENT["card:779741"]={"id":"card:779741","ty":"card","sourceId":"779741","title":"『投片計劃參數設定作業』的作業重點有哪些？","ver":"GP4以上","topic":"計劃","keywords":["計劃","存檔","一筆"],"y":"explain","answer":"■作業重點1.本作業存檔時，一併更新MPS 參數設定建立作業之「需求計算方式」為本作業的需求計算方式。2.本作業開啟時即預設第一筆資料，只能修改，不能新增、刪除、查詢。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
