self.KB_CONTENT["field:751387"]={"id":"field:751387","ty":"field","sourceId":"751387","title":"期間","ver":"iGP","topic":"","keywords":[],"job":"股東權益變動表","code":"","answer":"* 指報表的列印期間。* 若選擇會計年度＝2010年，期間＝全年，則表頭期間為2010/01/01~2010/12/31。* 若選擇會計年度＝2010年，期間＝半年，則表頭期間為2010/01/01~2010/06/30。","file":"fields.jsonl"};
