self.KB_CONTENT["field:752944"]={"id":"field:752944","ty":"field","sourceId":"752944","title":"選擇列印種類","ver":"iGP","topic":"","keywords":[],"job":"營運部門分類帳表","code":"","answer":"* 分為1.總分類帳及2.明細分類帳二種。","file":"fields.jsonl"};
self.KB_CONTENT["field:751592"]={"id":"field:751592","ty":"field","sourceId":"751592","title":"選擇傳票日期","ver":"iGP","topic":"","keywords":[],"job":"總分類帳","code":"ACT.ML002","answer":"* 可點選(icon)或[F2]日期快手查詢。若空白表全部。","file":"fields.jsonl"};
